// Monaco Editor 动态加载模块
// 按需加载编辑器核心和语言包，避免首屏加载大量代码

// 已加载的语言集合，避免重复导入
const loadedLanguages = new Set<string>();
let monacoPromise: Promise<typeof import("monaco-editor/esm/vs/editor/editor.api")> | null = null;

/**
 * 动态加载指定语言的语法高亮支持
 * 使用显式 switch 确保 Vite 能静态分析并生成独立 chunk
 */
const loadLanguageModule = async (language: string): Promise<void> => {
  switch (language) {
    case "c":
    case "cpp":
      await import("monaco-editor/esm/vs/basic-languages/cpp/cpp.contribution");
      break;
    case "java":
      await import("monaco-editor/esm/vs/basic-languages/java/java.contribution");
      break;
    case "python":
      await import("monaco-editor/esm/vs/basic-languages/python/python.contribution");
      break;
    case "pascal":
      await import("monaco-editor/esm/vs/basic-languages/pascal/pascal.contribution");
      break;
    case "go":
      await import("monaco-editor/esm/vs/basic-languages/go/go.contribution");
      break;
    case "lua":
      await import("monaco-editor/esm/vs/basic-languages/lua/lua.contribution");
      break;
    case "typescript":
      await import("monaco-editor/esm/vs/basic-languages/typescript/typescript.contribution");
      break;
    case "rust":
      await import("monaco-editor/esm/vs/basic-languages/rust/rust.contribution");
      break;
    case "csharp":
      await import("monaco-editor/esm/vs/basic-languages/csharp/csharp.contribution");
      break;
    default:
      console.warn(`Unknown monaco language: ${language}`);
      return;
  }
};

/**
 * 异步加载 Monaco Editor 核心
 * 首次调用时触发加载，后续调用返回缓存的 Promise
 */
export const loadMonaco = () => {
  if (!monacoPromise) {
    monacoPromise = (async () => {
      // 动态导入 monaco editor 核心 API
      const monaco = await import("monaco-editor/esm/vs/editor/editor.api");
      // 加载基础编辑器功能
      await import("monaco-editor/esm/vs/editor/editor.all.js");
      return monaco;
    })();
  }
  return monacoPromise;
};

/**
 * 动态加载指定语言的语法高亮支持
 * @param language 语言标识（如 "cpp", "java", "python" 等）
 */
export const loadMonacoLanguage = async (language: string) => {
  if (!language || language === "text" || loadedLanguages.has(language)) {
    return;
  }

  try {
    await loadLanguageModule(language);
    loadedLanguages.add(language);
  } catch (e) {
    console.error(`Failed to load monaco language: ${language}`, e);
  }
};

/**
 * 一次性加载 Monaco 核心并加载指定语言
 * 组件初始化编辑器时可以直接调用此函数
 */
export const loadMonacoWithLanguage = async (language?: string) => {
  const monaco = await loadMonaco();
  if (language) {
    await loadMonacoLanguage(language);
  }
  return monaco;
};
